      formula("r5-port", "Two-asset variance and safety-first ratio", String.raw`\sigma_p^2=w_A^2\sigma_A^2+w_B^2\sigma_B^2+2w_Aw_B\operatorname{Cov}(A,B),\quad SF=\frac{E(R_p)-R_L}{\sigma_p}`, [["w_A,w_B", "Portfolio weights", "decimal fraction"], ["\\sigma_A,\\sigma_B,\\sigma_p", "Asset and portfolio volatility", "decimal return"], ["R_L", "Minimum acceptable return", "decimal return"], ["SF", "Safety-first ratio", "unitless"]], ["Weights are fixed over the return horizon.", "Comparing SF as an exact shortfall-probability ranking assumes normally distributed returns."], "Weights sum to 1; sigma p>0 for SF. Handle a zero-volatility portfolio separately.", "SF measures how far expected return lies above the threshold in standard-deviation units.")
